use std::collections::BTreeMap;
use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut m: BTreeMap<String, i128> = BTreeMap::new();
    let mut out = String::new();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        let t: Vec<&str> = line.split_whitespace().collect();
        if t.is_empty() {
            continue;
        }
        let amt = |s: &str| -> i128 { s.parse::<i128>().unwrap_or(0) };
        let res: String = match t[0] {
            "open" if t.len() >= 3 => {
                let a = amt(t[2]);
                if a < 0 {
                    "error: invalid amount".into()
                } else if m.contains_key(t[1]) {
                    "error: duplicate account".into()
                } else {
                    m.insert(t[1].to_string(), a);
                    "ok".into()
                }
            }
            "deposit" | "withdraw" if t.len() >= 3 => {
                let a = amt(t[2]);
                if a <= 0 {
                    "error: invalid amount".into()
                } else if !m.contains_key(t[1]) {
                    format!("error: unknown account {}", t[1])
                } else {
                    let b = m.get_mut(t[1]).unwrap();
                    if t[0] == "deposit" {
                        *b += a;
                        "ok".into()
                    } else if *b < a {
                        "error: insufficient funds".into()
                    } else {
                        *b -= a;
                        "ok".into()
                    }
                }
            }
            "transfer" if t.len() >= 4 => {
                let a = amt(t[3]);
                if a <= 0 {
                    "error: invalid amount".into()
                } else if !m.contains_key(t[1]) {
                    format!("error: unknown account {}", t[1])
                } else if !m.contains_key(t[2]) {
                    format!("error: unknown account {}", t[2])
                } else if t[1] == t[2] {
                    "error: same account".into()
                } else if m[t[1]] < a {
                    "error: insufficient funds".into()
                } else {
                    *m.get_mut(t[1]).unwrap() -= a;
                    *m.get_mut(t[2]).unwrap() += a;
                    "ok".into()
                }
            }
            "balance" if t.len() >= 2 => match m.get(t[1]) {
                Some(b) => b.to_string(),
                None => format!("error: unknown account {}", t[1]),
            },
            _ => continue,
        };
        out.push_str(&res);
        out.push('\n');
    }
    for (k, v) in &m {
        out.push_str(&format!("{} {}\n", k, v));
    }
    print!("{}", out);
}

